import Foundation

// Try to use simctl to get the app and interact with it
// This is a simple approach to send a tap at the notifications button location
let process = Process()
process.executableURL = URL(fileURLWithPath: "/usr/bin/env")
process.arguments = ["osascript", "-"]
let pipe = Pipe()
process.standardInput = pipe

let script = """
tell application "System Events"
    tell application process "Simulator"
        click button "Notifications" of window 1
    end tell
end tell
"""

if let data = script.data(using: .utf8) {
    pipe.fileHandleForWriting.write(data)
    try? pipe.fileHandleForWriting.close()
}

try? process.run()
process.waitUntilExit()
EOF
