    # Check if there's a socket file for the simulator
    simulator_sockets_path = os.path.expanduser("~/.lldb/simulator_sockets")
    if os.path.exists(simulator_sockets_path):
        print(f"Simulator sockets directory exists: {simulator_sockets_path}")
        for item in os.listdir(simulator_sockets_path):
            print(f"  Socket: {item}")
except Exception as e:
    print(f"No simulator sockets found: {e}")

try:
    # Try to get the simulator's container path
    result = subprocess.run(
        ["xcrun", "simctl", "get_app_container", device_id, "xyz.blueskyweb.app"],
        capture_output=True,
        text=True
    )
    if result.stdout:
        print(f"App container: {result.stdout}")
except Exception as e:
    print(f"Error getting app container: {e}")

try:
    # Try to list all available services on the simulator
    result = subprocess.run(
        ["xcrun", "simctl", "spawn", device_id, "launchctl", "list"],
        capture_output=True,
        text=True,
        timeout=5
    )
    print("Available services:")
    for line in result.stdout.split('\n')[:10]:
        if line:
            print(f"  {line}")
except Exception as e:
    print(f"Error listing services: {e}")
EOF

